insert into public.vehicles (slug, manufacturer, model, variant, generation, model_year, model_year_status, body_style, drivetrain, layout, engine, facts_status, summary, specs, sort_order) values
  ('porsche-911', 'Porsche', '911', 'Carrera T', '992.2', 2026, 'unverified', 'Coupé', 'RWD', 'Rear-engine', '3.0 L twin-turbo flat-six', 'unverified', 'The driver-focused take on the current 911: lighter trim, a manual gearbox and the engine where it has always been.', '[{"label":"Power","detail":null},{"label":"Torque","detail":null},{"label":"0–100 km/h","detail":null},{"label":"Top speed","detail":null},{"label":"Kerb weight","detail":null},{"label":"Length","detail":null},{"label":"Width","detail":null},{"label":"Height","detail":null},{"label":"Wheelbase","detail":null}]'::jsonb, 0),
  ('bmw-m4', 'BMW', 'M4', 'Competition', 'G82', 2021, 'unverified', 'Coupé', 'RWD', 'Front-engine', '3.0 L twin-turbo inline-six', 'unverified', 'A long-bonnet coupé built around a straight-six, with a stance that splits opinion and a chassis that settles it.', '[{"label":"Power","detail":null},{"label":"Torque","detail":null},{"label":"0–100 km/h","detail":null},{"label":"Top speed","detail":null},{"label":"Kerb weight","detail":null},{"label":"Length","detail":null},{"label":"Width","detail":null},{"label":"Height","detail":null},{"label":"Wheelbase","detail":null}]'::jsonb, 1),
  ('nissan-gt-r', 'Nissan', 'GT-R', 'NISMO', 'R35', 2024, 'unverified', 'Coupé', 'AWD', 'Front-engine', '3.8 L twin-turbo V6', 'unverified', 'The final evolution of a car that spent seventeen years embarrassing more expensive machinery with grip and a hand-built V6.', '[{"label":"Power","detail":null},{"label":"Torque","detail":null},{"label":"0–100 km/h","detail":null},{"label":"Top speed","detail":null},{"label":"Kerb weight","detail":null},{"label":"Length","detail":null},{"label":"Width","detail":null},{"label":"Height","detail":null},{"label":"Wheelbase","detail":null}]'::jsonb, 2),
  ('ferrari-488', 'Ferrari', '488', 'GTB', 'F142M', 2016, 'unverified', 'Supercar', 'RWD', 'Mid-engine', '3.9 L twin-turbo V8', 'unverified', 'The berlinetta that brought turbocharging back to Maranello''s mid-engined V8 line, shaped as much by airflow as by eye.', '[{"label":"Power","detail":null},{"label":"Torque","detail":null},{"label":"0–100 km/h","detail":null},{"label":"Top speed","detail":null},{"label":"Kerb weight","detail":null},{"label":"Length","detail":null},{"label":"Width","detail":null},{"label":"Height","detail":null},{"label":"Wheelbase","detail":null}]'::jsonb, 3),
  ('audi-rs7', 'Audi', 'RS7', 'Sportback', 'C8', 2020, 'unverified', 'Sportback', 'AWD', 'Front-engine', '4.0 L twin-turbo V8', 'unverified', 'Five doors, four seats and a twin-turbo V8 under a fastback roofline. The practical one, on paper.', '[{"label":"Power","detail":null},{"label":"Torque","detail":null},{"label":"0–100 km/h","detail":null},{"label":"Top speed","detail":null},{"label":"Kerb weight","detail":null},{"label":"Length","detail":null},{"label":"Width","detail":null},{"label":"Height","detail":null},{"label":"Wheelbase","detail":null}]'::jsonb, 4),
  ('toyota-supra', 'Toyota', 'GR Supra', '3.0', 'A90', 2020, 'unverified', 'Coupé', 'RWD', 'Front-engine', '3.0 L turbo inline-six', 'unverified', 'A short wheelbase, a double-bubble roof and a straight-six: the return of a name that tuners never let go of.', '[{"label":"Power","detail":null},{"label":"Torque","detail":null},{"label":"0–100 km/h","detail":null},{"label":"Top speed","detail":null},{"label":"Kerb weight","detail":null},{"label":"Length","detail":null},{"label":"Width","detail":null},{"label":"Height","detail":null},{"label":"Wheelbase","detail":null}]'::jsonb, 5),
  ('mercedes-amg-gt', 'Mercedes-AMG', 'GT', '63 4MATIC+ Coupé', 'C192', 2024, 'unverified', 'Coupé', 'AWD', 'Front-engine', '4.0 L twin-turbo V8', 'unverified', 'The second-generation AMG GT trades the old car''s rawness for all-wheel drive, rear seats and long-distance pace.', '[{"label":"Power","detail":null},{"label":"Torque","detail":null},{"label":"0–100 km/h","detail":null},{"label":"Top speed","detail":null},{"label":"Kerb weight","detail":null},{"label":"Length","detail":null},{"label":"Width","detail":null},{"label":"Height","detail":null},{"label":"Wheelbase","detail":null}]'::jsonb, 6),
  ('mclaren-720s', 'McLaren', '720S', 'Coupé', 'P14', 2017, 'unverified', 'Supercar', 'RWD', 'Mid-engine', '4.0 L twin-turbo V8', 'unverified', 'A carbon tub, dihedral doors and bodywork with no visible side intakes. Air goes through the car, not around it.', '[{"label":"Power","detail":null},{"label":"Torque","detail":null},{"label":"0–100 km/h","detail":null},{"label":"Top speed","detail":null},{"label":"Kerb weight","detail":null},{"label":"Length","detail":null},{"label":"Width","detail":null},{"label":"Height","detail":null},{"label":"Wheelbase","detail":null}]'::jsonb, 7),
  ('lamborghini-huracan', 'Lamborghini', 'Huracán', 'EVO RWD', 'LB724', 2021, 'unverified', 'Supercar', 'RWD', 'Mid-engine', '5.2 L naturally aspirated V10', 'unverified', 'A naturally aspirated V10 driving the rear wheels only. The Huracán with the fewest systems between you and it.', '[{"label":"Power","detail":null},{"label":"Torque","detail":null},{"label":"0–100 km/h","detail":null},{"label":"Top speed","detail":null},{"label":"Kerb weight","detail":null},{"label":"Length","detail":null},{"label":"Width","detail":null},{"label":"Height","detail":null},{"label":"Wheelbase","detail":null}]'::jsonb, 8)
